cat > /tmp/probe/work-cpp-parsing-hard/sweep.sh <<'EOS'
#!/bin/bash
# usage: sweep.sh <dir> [args...]  -- prints compact per-file result
d="$1"; shift
cd "$d" || exit 1
for f in $(ls | grep -E '\.(cpp|c|cc|cxx|h|hpp)$' | sort); do
  /workspace/executable "$@" "$f" > "$f.o" 2> "$f.e"; rc=$?
  # strip the "Checking ... " progress + checkersReport noise
  filt=$(grep -v -e '^Checking ' -e 'checkersReport' -e '^$' "$f.e")
  if [ -z "$filt" ]; then
    echo "[$f] CLEAN (exit=$rc)"
  else
    echo "[$f] exit=$rc"
    printf '%s\n' "$filt" | sed 's/^/    /'
  fi
done
EOS
